def categorize_transaction(transaction: Transaction) -> str:
    if transaction.recipient == get_iban():
        return "Transfer to self"
    elif transaction.subject.lower() in ["rent", "lease"]:
        return "Rent"
    elif transaction.subject.lower() in ["groceries", "supermarket"]:
        return "Groceries"
    elif transaction.subject.lower() in ["dining", "restaurant"]:
        return "Dining"
    else:
        return "Other"

