    if transaction.date.startswith(str(datetime.now().year)):
        category = categorize_transaction(transaction)
        if category not in categories:
            categories[category] = []
        categories[category].append(transaction.amount)

summary = {}
for category, amounts in categories.items():
    summary[category] = sum(amounts)

for category, total_amount in summary.items():
    print(f"{category}: {total_amount}")
